cudaDeviceProp prop;
cudaGetDeviceProperties(&prop, 0);

printf("Name: %s\n", prop.name);
printf("Max threads/block: %d\n",
       prop.maxThreadsPerBlock);

int i = blockIdx.x * blockDim.x + threadIdx.x;

if (i < n) {
    c[i] = a[i] + b[i];
}

int threadsPerBlock = 256;
int blocksPerGrid = (n + threadsPerBlock - 1)
                    / threadsPerBlock;

VecAdd<<<blocksPerGrid, threadsPerBlock>>>(d_a,d_b,d_c,n);

float *d_a;
cudaMalloc((void**)&d_a, n * sizeof(float));

/* use d_a on GPU */

cudaFree(d_a);

cudaError_t err = cudaGetLastError();
if (err != cudaSuccess) {
    printf("CUDA error: %s\n",
           cudaGetErrorString(err));
}

for (int i = 0; i < n; i++) {
    c[i] = a[i] + b[i];
}

__global__ void VecAdd(float* a, float* b,
                       float* c, int n) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) c[i] = a[i] + b[i];
}

__global__ void TrapKernel(double a, double h,
                           int n, double* partial) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i > 0 && i < n) {
        double x = a + i*h;
        partial[i] = f(x);
    }
}

extern __shared__ double sdata[];
int tid = threadIdx.x;
sdata[tid] = local_value;
__syncthreads();

/* reduce sdata within block */
if (tid == 0) block_sums[blockIdx.x] = sdata[0];
